using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, patterns, and quantitative reasoning." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Analysis of literature, writing, and critical communication." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Understanding of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, societies, and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 peer-reviewed papers and leads the university's AI research lab.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez focuses on applied mathematics and statistics. He has 15 years of teaching experience and received the Distinguished Teaching Award in 2023.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah O'Brien", Title = "Professor of English", Bio = "Prof. O'Brien is an acclaimed author and literary critic specializing in contemporary American fiction. Her essays appear regularly in major literary journals.", Email = "sobrien@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Professor of Physics", Bio = "Dr. Park's research in quantum mechanics has earned international recognition. He previously worked at CERN and holds two patents in particle detection technology.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Gonzalez", Title = "Associate Professor of History", Bio = "Dr. Gonzalez is an expert in Latin American history and post-colonial studies. She has authored three books on social movements in the Americas.", Email = "mgonzalez@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Assistant Professor of Computer Science", Bio = "Dr. Kim specializes in cybersecurity and distributed systems. Before joining academia, he spent a decade in industry at leading technology companies.", Email = "dkim@university.edu" },
            new() { Id = 7, Name = "Dr. Emily Taylor", Title = "Professor of Mathematics", Bio = "Dr. Taylor is an expert in abstract algebra and number theory. She has mentored over 20 graduate students and serves on several editorial boards.", Email = "etaylor@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques. Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 6, IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Concepts of database design, SQL, normalization, and transaction management. Includes hands-on projects with relational and NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Center 102", DepartmentId = 1, InstructorId = 6, IsFeatured = false },
            new() { Id = 4, Code = "CS 450", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Hall 401", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 110", DepartmentId = 2, InstructorId = 2, IsFeatured = false },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 205", DepartmentId = 2, InstructorId = 7, IsFeatured = true },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Building 110", DepartmentId = 2, InstructorId = 2, IsFeatured = false },
            new() { Id = 8, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop effective writing skills through essays, research papers, and rhetorical analysis. Focus on clarity, argumentation, and revision.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Hall 103", DepartmentId = 3, InstructorId = 3, IsFeatured = false },
            new() { Id = 9, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major authors, themes, and literary movements.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Hall 210", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions. Co-requisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Thu Lab 2:00–4:50 PM", Location = "Physics Lab 100", DepartmentId = 4, InstructorId = 4, IsFeatured = false },
            new() { Id = 11, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory. Prerequisites: PHYS 201, MATH 201.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Lab 300", DepartmentId = 4, InstructorId = 4, IsFeatured = false },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of global civilizations from prehistory through the Renaissance, covering major political, cultural, and economic developments.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Liberal Arts 150", DepartmentId = 5, InstructorId = 5, IsFeatured = false },
            new() { Id = 13, Code = "HIST 250", Title = "Modern Latin America", Description = "Political, social, and cultural history of Latin America from independence movements to contemporary issues.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 220", DepartmentId = 5, InstructorId = 5, IsFeatured = true },
        };

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        IEnumerable<Course> query = _courses;

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

