@page "/courses"
@rendermode InteractiveServer

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

@inject ICatalogService Catalog

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, description, or instructor…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name (@dept.Code)</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@{
    var courses = Catalog.GetCourses(searchTerm, selectedDepartmentId > 0 ? selectedDepartmentId : null);
}

<p class="text-muted">Showing @courses.Count course(s)</p>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead class="table-dark">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.Department.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Instructor.Name</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string? searchTerm;
    private int selectedDepartmentId;

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    protected override void OnInitialized()
    {
        if (DepartmentId.HasValue)
        {
            selectedDepartmentId = DepartmentId.Value;
        }
    }

    private void ClearFilters()
    {
        searchTerm = null;
        selectedDepartmentId = 0;
    }
}

@page "/enroll"

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

@inject ICatalogService Catalog

<h1>Enrollment Request</h1>
<p>Complete the form below to submit an enrollment request. You will receive a confirmation from the registrar's office.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
           <strong>@selectedCourseTitle</strong> has been received.</p>
        <hr />
        <p class="mb-0">The registrar's office will review your request and notify you at your university email.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <EditForm Model="Model" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in Catalog.GetCourses())
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Browse Courses</a>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private string? selectedCourseTitle;

    protected override void OnInitialized()
    {
        if (!submitted && CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
        submitted = true;
    }
}

